name: Codex Review - Notify Code Owner

on:
  pull_request:
    types: [opened, synchronize, reopened]
    branches: [main, develop]

permissions:
  contents: read
  pull-requests: write

jobs:
  notify-code-owner:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Get code owner
        id: get-code-owner
        run: |
          # Extract code owners from CODEOWNERS file
          CODE_OWNER=$(grep -E "^\.github/workflows/codex-review-notify-code-owner\.yml" .github/CODEOWNERS | awk '{print $2}' | head -1)
          echo "code_owner=$CODE_OWNER" >> $GITHUB_ENV

      - name: Notify code owner
        if: env.code_owner != ''
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { code_owner } = process.env;

            // Get PR details
            const prNumber = context.payload.pull_request.number;
            const prTitle = context.payload.pull_request.title;
            const prUrl = context.payload.pull_request.html_url;
            const author = context.payload.pull_request.user.login;

            // Create notification message
            const message = `@${code_owner} - A new pull request has been opened that requires your review:\n\n**Title:** ${prTitle}\n**Author:** ${author}\n**PR Link:** ${prUrl}`;

            // Add comment to PR
            await github.rest.issues.createComment({
              issue_number: prNumber,
              owner: context.repo.owner,
              repo: context.repo.repo,
              body: message
            });
